targets.expr:
sum by (reason_category)(
  label_replace(
    label_replace(
      label_replace(
        label_replace(
          rate(search_refresh_skipped_total[5m]),
          "reason_category", "rate_limited", "reason", "rate limited:.*"
        ),
        "reason_category", "no_updates", "reason", "no pending updates"
      ),
      "reason_category", "in_progress", "reason", ".*in progress.*"
    ),
    "reason_category", "other", "reason", "^(?!rate_limited|no_updates|in_progress$).*"
  )
)
